using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Text;using V15Voice;
public static class LocalAiSafetyTests {
 static int count;static void Check(bool value,string label){if(!value)throw new Exception(label);Console.WriteLine("PASS "+label);count++;}static void Reject(Action action,string label){try{action();}catch{Check(true,label);return;}throw new Exception(label);}
 static string Zip(string folder,string name,params string[] paths){string p=Path.Combine(folder,name+".zip");using(var z=ZipFile.Open(p,ZipArchiveMode.Create)){foreach(var path in paths)using(var stream=z.CreateEntry(path).Open()){byte[] data=Encoding.UTF8.GetBytes("test runtime");stream.Write(data,0,data.Length);}}return p;}
 public static void Main(){string folder=Path.Combine(Path.GetTempPath(),"V15 local AI safety "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string file=Path.Combine(folder,"part.bin");File.WriteAllText(file,"verified data");long size=new FileInfo(file).Length;string hash=StateFiles.Hash(file).ToLowerInvariant();LocalAi.VerifyFile(file,size,hash,()=>false);Check(true,"SHA256 and exact size verification accepts matching bytes");Reject(()=>LocalAi.VerifyFile(file,size+1,hash,()=>false),"Wrong model/runtime size is rejected");Reject(()=>LocalAi.VerifyFile(file,size,new string('0',64),()=>false),"Wrong SHA256 is rejected");Reject(()=>LocalAi.VerifyFile(file,size,hash,()=>true),"Cancel is honored even when checksum was cached");File.WriteAllText(file,"tampered data");Reject(()=>LocalAi.VerifyFile(file,size,hash,()=>false),"Changed bytes invalidate cached verification");
  string good=Zip(folder,"good","llama-completion.exe","llama.dll","LICENSE-test");string target=Path.Combine(folder,"runtime");LocalAi.ExtractRuntime(good,target,()=>false);Check(File.Exists(Path.Combine(target,"llama-completion.exe"))&&File.Exists(Path.Combine(target,"llama.dll")),"Runtime ZIP extracts expected files into isolated folder");
  foreach(string name in new[]{"../escape.exe","/absolute.exe","a/inside.dll","C:escape.exe","..hidden"}){string zip=Zip(folder,Guid.NewGuid().ToString("N"),"llama-completion.exe",name);Reject(()=>LocalAi.ExtractRuntime(zip,target,()=>false),"Reject unsafe runtime path "+name);}Check(File.ReadAllText(Path.Combine(target,"llama-completion.exe"))=="test runtime"&&!File.Exists(Path.Combine(folder,"escape.exe")),"Rejected ZIP does not replace installed runtime or escape directory");Reject(()=>LocalAi.ExtractRuntime(Zip(folder,"missing","llama.dll"),target,()=>false),"Incomplete runtime is rejected before publication");Reject(()=>LocalAi.ExtractRuntime(good,target,()=>true),"Cancellation cleans extraction staging");Check(!Directory.GetDirectories(folder,"runtime.stage-*").Any(),"Extraction staging is removed after success, failure and stop");
  string source=File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"source","LocalAi.cs"));Check(source.Contains(" --offline ")&&!source.Contains("gemini.google.com")&&!source.Contains("api.openai.com"),"Inference uses explicit offline runtime; setup downloads are separate");Console.WriteLine("TOTAL LOCAL AI SAFETY "+count+" passed.");}
}
